  ('hardware-building', 'Hardware building', 900),
  ('medicine-health', 'Medicine health', 900),
  ('photography-events', 'Photography events', 900),
  ('plumbing-electrical', 'Plumbing electrical', 900),
  ('stationery', 'Stationery', 900),
  ('water-energy', 'Water energy', 900)
on conflict (id) do nothing;

