update public.product_types t set size_chart_id = c.id from public.size_charts c
where c.category is null and lower(btrim(c.name)) = 'baby clothes (months)' and t.id = any(array['baby-clothing']::text[]) and t.size_chart_id is null;
update public.product_types t set size_chart_id = c.id from public.size_charts c
where c.category is null and lower(btrim(c.name)) = 'school uniform (chest size)' and t.id = any(array['school-uniform']::text[]) and t.size_chart_id is null;
